import { Component, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Router } from '@angular/router';
import { UserService } from '../_services/user.service';
import { BadgeModule } from 'primeng/badge';
import { AuthService } from '../_services/auth.service';
import { PanelModule } from 'primeng/panel';

@Component({
    selector: 'app-home',
    standalone: true,
    imports: [BadgeModule, PanelModule, CommonModule],
    templateUrl: './home.component.html',
    styleUrl: './home.component.scss',
})
export class HomeComponent {
    readonly router = inject(Router);
    readonly userService = inject(UserService);
    readonly authService = inject(AuthService);

    navigate(route: string) {
        this.router.navigate([route]);
    }
    userType = this.userService.userType;
    paymentDialogVisible = false;

    debtDialogVisible = false;

    expensesDialogVisible: boolean = false;
    selectedPayment: any;
    dialogMode: string = 'add';

    openExpenseDialog() {
        this.expensesDialogVisible = true;
    }

    closeDialog() {
        this.expensesDialogVisible = false;
    }
}
