import {
    Component,
    ElementRef,
    inject,
    OnInit,
    ViewChild,
} from '@angular/core';
import { FormControl, FormGroup, Validators } from '@angular/forms';
import { AuthService } from '../_services/auth.service';
import { finalize } from 'rxjs';
import { NotificationsService } from '../_services/notifications.service';
import { Router } from '@angular/router';
import packageJson from '../../../package.json';

@Component({
    selector: 'app-login',
    templateUrl: './login.component.html',
    styleUrls: ['./login.component.scss'],
})
export class LoginComponent implements OnInit {
    @ViewChild('username') usernameElement: ElementRef;

    constructor(
        private authService: AuthService,
        private notificationService: NotificationsService
    ) {}

    readonly router = inject(Router);

    ngOnInit(): void {
        this.authService.logout();
    }

    loginForm = new FormGroup({
        username: new FormControl('', Validators.required),
        password: new FormControl('', Validators.required),
    });

    usernameControl = this.loginForm.controls.username;
    passwordControl = this.loginForm.controls.password;

    // define loader
    loader: boolean = false;

    submitLogin() {
        if (this.loginForm.valid) {
            // to be implemented, activate loader
            // .......
            this.loader = true;
            this.authService
                .login({
                    username: this.usernameControl.value!,
                    password: this.passwordControl.value!,
                })
                .pipe(
                    finalize(() => {
                        this.loader = false;
                    })
                )
                .subscribe({
                    error: (error) => {
                        console.log(error);

                        this.usernameElement.nativeElement.focus();
                        this.notificationService.handleError(error, 'login');
                        this.loginForm.reset();
                    },
                    complete: () => this.loginForm.reset(),
                });
        }
    }

    // refresh and update for PWA
    updateApp() {
        this.router.navigate(['/update']);
    }

    public version: string = packageJson.version;
}
