import {
    ChangeDetectorRef,
    inject,
    Injectable,
    NgZone,
    signal,
} from '@angular/core';

import packageJson from '../../../package.json';
import { HttpClient } from '@angular/common/http';
import { NotificationsService } from '../_services/notifications.service';
import { ApiService } from '../_services/api.service';

@Injectable({
    providedIn: 'root',
})
export class UpdateService {
    readonly ngZone = inject(NgZone);
    readonly http = inject(HttpClient);
    readonly notificationService = inject(NotificationsService);
    readonly api = inject(ApiService);

    public version: string = packageJson.version;

    public feedback = signal<string | null>(null);
    public checking = signal(false);
    public checked = signal(false);
    public updateAvailable = signal(false);
    public downloadingUpdate = signal(false);
    public downloadProgress = signal(null);
    public installAvailable = signal(false);

    // check if electron or web
    isElectron = (window as any).electron ? true : false;

    // electron window instance
    electron = (window as any).electron;

    constructor() {
        // checking for update
        if ((window as any).electron) {
            (window as any).electron.checkingForUpdate((event, data) => {
                this.ngZone.run(() => {
                    this.checking.set(true);
                    this.feedback.set(data);
                });
            });
        }

        // update available
        if ((window as any).electron) {
            (window as any).electron.updateAvailable((event, data) => {
                this.ngZone.run(() => {
                    this.checking.set(false);
                    this.updateAvailable.set(true);
                    this.feedback.set(`version ${data.version} is available.`);
                });
            });
        }

        // update not available
        if ((window as any).electron) {
            (window as any).electron.updateNotAvailable((event, data) => {
                this.ngZone.run(() => {
                    this.checking.set(false);
                    this.checked.set(false);
                    this.feedback.set('Your current version is up-to-date!');
                });
            });
        }

        // update error
        if ((window as any).electron) {
            (window as any).electron.error((event, data) => {
                this.ngZone.run(() => {
                    this.checking.set(false);
                    this.checked.set(false);
                    this.updateAvailable.set(false);
                    this.feedback.set('An error has occured!');
                    console.log(data);
                });
            });
        }

        // downloading update
        if ((window as any).electron) {
            (window as any).electron.downloading((event, data) => {
                this.ngZone.run(() => {
                    this.checking.set(false);
                    this.updateAvailable.set(false);
                    this.downloadingUpdate.set(true);
                    console.log(parseInt(data.percent));

                    this.downloadProgress.set(parseInt(data.percent));
                    this.feedback.set(
                        `Downloading: ${data.percent.toFixed(2)}%`,
                    );
                    console.log(data);
                });
            });
        }

        // download completed
        if (this.isElectron) {
            this.electron.downloadCompleted((event, data) => {
                this.ngZone.run(() => {
                    this.checking.set(false);
                    this.downloadingUpdate.set(false);
                    this.updateAvailable.set(false);
                    this.installAvailable.set(true);
                    this.feedback.set(
                        `Ready to install version ${data.version} of size ${(
                            data.files[0]['size'] / 1000000
                        ).toFixed(2)} MB.`,
                    );
                    console.log(data);
                });
            });
        }
    }

    async checkForUpdate() {
        if (this.isElectron) {
            this.checked.set(true);
            this.feedback.set(null);
            await this.electron.send('update');
        } else {
            this.checked.set(true);
            if ('serviceWorker' in navigator) {
                navigator.serviceWorker
                    .getRegistration()
                    .then((registration) => {
                        if (registration) {
                            registration
                                .unregister()
                                .then(() => window.location.reload()); // Reload after unregistration
                        } else {
                            this.notificationService.showInfo(
                                'No update available',
                            );
                            this.checked.set(false);
                        }
                    });
            }
        }
    }

    async downloadUpdate() {
        if ((window as any).electron) {
            this.updateAvailable.set(false);
            this.checking.set(true);
            await (window as any).electron.send('download');
        }
    }

    async applyUpdate() {
        if ((window as any).electron) {
            await (window as any).electron.send('applyUpdate');
        }
    }

    // fix database
    // fixDatabase() {
    //     this.http.patch(`${this.api.host}/update`, null).subscribe({
    //         next: (res: any) => {
    //             this.notificationService.showSuccess(res.message, 'home');
    //         },
    //         error: (error: HttpErrorResponse) => {
    //             this.notificationService.showError(error.error.message, 'home');
    //         },
    //     });
    // }
}
