import { HttpClient } from '@angular/common/http';
import { Injectable, signal } from '@angular/core';
import { TokenStorageService } from './token-storage.service';
import { Router } from '@angular/router';
import { ApiService } from './api.service';
import { BehaviorSubject, Observable } from 'rxjs';
import { tap } from 'rxjs/operators';

import { Credentials, LoginResponse } from '../core/interfaces/login.interface';
import { UserService } from './user.service';

@Injectable({
    providedIn: 'root',
})
export class AuthService {
    constructor(
        private http: HttpClient,
        private tokenStorage: TokenStorageService,
        private router: Router,
        private api: ApiService,
        private userService: UserService
    ) {}

    private host = this.api.host;

    isLoggedIn: BehaviorSubject<boolean> = new BehaviorSubject(
        this.tokenStorage.getToken() !== null
    );
    isAdmin = signal(this.tokenStorage.getType() === 'admin');

    login(credentials: Credentials): Observable<LoginResponse> {
        return this.http
            .post<LoginResponse>(`${this.host}/auth/login`, {
                username: credentials.username,
                password: credentials.password,
            })
            .pipe(
                tap((res) => {
                    console.log(res.user_type);

                    this.tokenStorage.saveUser(res.username);
                    this.tokenStorage.saveToken(res.token);
                    this.tokenStorage.saveType(res.user_type);
                    this.userService.loggedInUser.set(res.username);
                    this.userService.userType.set(res.user_type);
                    this.isLoggedIn.next(true);
                    this.router.navigate(['/home']);
                })
            );
    }

    logout(): void {
        window.sessionStorage.clear();
        localStorage.removeItem('auth-token');
        this.isLoggedIn.next(false);
        this.router.navigate(['/login']);
    }
}
