import { Injectable } from '@angular/core';
import * as moment from 'moment';

@Injectable({
    providedIn: 'root',
})
export class DateService {
    constructor() {}

    getCurrentDate(): string {
        return moment().format('YYYY-MM-DD');
    }

    getCurrentMonth(): number {
        return moment().month() + 1; // Adjust for zero-based month indexing in momentjs
    }

    getCurrentYear(): number {
        return moment().year();
    }

    // get start of day

    // get start of current month
    getStartOfCurrentMonth(): string {
        return moment().clone().startOf('month').format('YYYY-MM-DD');
    }

    getEndOfCurrentMonth(): string {
        return moment().clone().endOf('month').format('YYYY-MM-DD');
    }

    // get start of current year
    getStartOfYear(): string {
        return moment().startOf('year').format('YYYY-MM-DD');
    }

    getEndOfYear(): string {
        return moment().endOf('year').format('YYYY-MM-DD');
    }

    formatDate(date: any, format: string = 'YYYY-MM-DD'): string {
        return moment(date).format(format);
    }
}
