import {
    HttpClient,
    HttpErrorResponse,
    HttpHeaders,
    HttpParams,
} from '@angular/common/http';
import { inject, Injectable, signal } from '@angular/core';
import { interval, Observable, of, throwError } from 'rxjs';
import { catchError, startWith, switchMap } from 'rxjs/operators';
import { NotificationsService } from './notifications.service';
import { environment } from '../environment';

export interface RequestOptions {
    params?: HttpParams | { [param: string]: string | string[] };
    headers?: HttpHeaders | { [header: string]: string | string[] };
}

@Injectable({
    providedIn: 'root',
})
export class ApiService {
    readonly http = inject(HttpClient);
    readonly notificationService = inject(NotificationsService);

    isOnline = signal(false);

    constructor() {
        interval(5000)
            .pipe(
                startWith(0),
                switchMap(() =>
                    this.http
                        .get<{ status: string }>(this.buildUrl('health'))
                        .pipe(catchError(() => of({ status: 'offline' })))
                )
            )
            .subscribe((res) => {
                this.isOnline.set(res.status === 'ok' ? true : false);
            });
    }

    /**
     * Prepend base URL to endpoint
     */
    public host: String = environment.apiUri;
    private buildUrl(endpoint: string): string {
        return `${this.host.replace(/\/+$/, '')}/${endpoint.replace(
            /^\/+/,
            ''
        )}`;
    }

    /**
     * Send GET request
     */
    get<T>(endpoint: string, options: RequestOptions = {}): Observable<T> {
        return this.http
            .get<T>(this.buildUrl(endpoint), {
                params: options.params,
                headers: options.headers,
            })
            .pipe(catchError((error) => this.handleError(error)));
    }

    /**
     * Send POST request
     */
    post<T>(
        endpoint: string,
        body: any,
        options: RequestOptions = {}
    ): Observable<T> {
        return this.http
            .post<T>(this.buildUrl(endpoint), body, {
                params: options.params,
                headers: options.headers,
            })
            .pipe(catchError((error) => this.handleError(error)));
    }

    /**
     * Send PUT request
     */
    put<T>(
        endpoint: string,
        body: any,
        options: RequestOptions = {}
    ): Observable<T> {
        return this.http
            .put<T>(this.buildUrl(endpoint), body, {
                params: options.params,
                headers: options.headers,
            })
            .pipe(catchError((error) => this.handleError(error)));
    }

    /**
     * Send DELETE request
     */
    delete<T>(endpoint: string, options: RequestOptions = {}): Observable<T> {
        return this.http
            .delete<T>(this.buildUrl(endpoint), {
                params: options.params,
                headers: options.headers,
            })
            .pipe(catchError((error) => this.handleError(error)));
    }

    /**
     * Centralized error handling
     */
    public handleError(error: HttpErrorResponse): Observable<never> {
        let errorMessage = 'Unknown Error!!';
        if (error.error instanceof ErrorEvent) {
            console.log('client error');

            // Client-side Errors
            errorMessage = `${
                Object.hasOwn(error, 'error.error.message')
                    ? error.error.message
                    : error.error
            }`;
        } else {
            // Server-side Errors
            console.log('server error');
            if (error.error) {
                if (error.error.message) {
                    errorMessage = error.error.message;
                } else if (error.error.errors) {
                    if (error.error.errors[0].message) {
                        errorMessage = error.error.errors[0].message;
                    }
                } else {
                    errorMessage = error.error;
                }
            }
        }

        this.notificationService.showError(errorMessage, 'home');
        // throw error
        return throwError(() => error);
    }

    // check existance for nested object key
    hasNestedKey(obj: any, path: string | string[]): boolean {
        if (!obj || typeof obj !== 'object') return false;

        const keys = Array.isArray(path) ? path : path.split('.');

        let current = obj;
        for (const key of keys) {
            if (!Object.hasOwn(current, key)) {
                return false;
            }
            current = current[key];
        }
        return true;
    }
}
