import { ElementRef, Injectable, ViewChild } from '@angular/core';
import { HttpErrorResponse } from '@angular/common/http';
import { throwError } from 'rxjs';
import { MessageService } from 'primeng/api';

@Injectable({
    providedIn: 'root',
})
export class NotificationsService {
    constructor(public messageService: MessageService) {}

    successSound = new Audio('assets/sounds/ding-sound.mp3');
    errorSound = new Audio('assets/sounds/error-2.wav');

    public handleError(error: HttpErrorResponse, key: string) {
        let errorMessage = 'Unknown Error!';
        let errorToast = 'Unknown Error!!';
        if (error.error instanceof ErrorEvent) {
            // Client-side Errors
            errorMessage = `Error: ${error.error}`;
            errorToast = `${
                Object.hasOwn(error, 'error.error.message')
                    ? error.error.message
                    : error.error
            }`;
        } else {
            // Server-side Errors
            errorMessage = `Server error code: ${error.status}\n Message: ${error.error}`;
            errorToast = `${
                Object.hasOwn(error, 'error.error.message')
                    ? error.error.message
                    : error.error
            }`;
        }
        // console.log(error);
        this.messageService.add({
            severity: 'error',
            key: 'home',
            summary: 'Error',
            detail: errorToast,
        });

        // play audio
        this.errorSound.load();
        this.errorSound.play();

        return throwError(
            () => new Error('Something bad happened; please try again later.'),
        );
    }

    public showSuccess(msg: string, key: string = 'home') {
        this.messageService.add({
            severity: 'success',
            key: key,
            summary: 'Success',
            detail: msg,
        });

        // play audio
        this.successSound.load();
        this.successSound.play();
    }

    public showInfo(msg: string, key: string = 'home') {
        this.messageService.add({
            severity: 'info',
            key: key,
            summary: 'info',
            detail: msg,
        });
    }

    public showError(msg: string, key: string) {
        this.messageService.add({
            severity: 'error',
            key: key,
            summary: 'Error',
            detail: msg,
        });

        // play audio
        this.errorSound.load();
        this.errorSound.play();
    }

    // show socket message info
    public showSocketMessage(message: string, key: string) {
        this.messageService.add({
            severity: 'info',
            key: key,
            summary: 'Info',
            detail: `${message}`,
            life: 4000,
        });

        // this.notifySound.play();
    }
}
